}}_

_code{int sum_of_odd_numbers(struct tree_node * node) {
    if (node == NULL) {
        return 0;
    }

    int sum = 0;
    // Sprawdzamy, czy wartość węzła jest nieparzysta
    if (node->number % 2 != 0) {
        sum = node->number;
    }

    // Dodajemy sumę z lewego i prawego poddrzewa
    return sum + sum_of_odd_numbers(node->left) + sum_of_odd_numbers(node->right);
}}_

_code{bool is_palindrome(char word[], int first, int last) {
    // Warunek końcowy: wskaźniki się spotkały lub minęły - wszystkie znaki pasują
    if (first >= last) {
        return true;
    }

    // Jeśli znaki na krańcach są różne, nie jest to palindrom
    if (word[first] != word[last]) {
        return false;
    }

    // Wywołanie rekurencyjne dla zawężonego przedziału znaków
    return is_palindrome(word, first + 1, last - 1);
}}_

_code{unsigned int count_long_words(struct tree_node *node) {
    if (node == NULL) return 0;
    unsigned int count = (strlen(node->word) > 10) ? 1 : 0;
    return count + count_long_words(node->left) + count_long_words(node->right);
}}_

