_code{unsigned int find_number(struct list_node *node, int number) {
    if (node == NULL) return 0;
    if (node->data == number) return 1;
    return find_number(node->next, number);
}}_

_code{long int find_max(struct list_node *node) {
    if (node == NULL) return -1;
    if (node->next == NULL) return node->number;

    long int max_in_rest = find_max(node->next);
    return (node->number > max_in_rest) ? node->number : max_in_rest;
}}_

_code{unsigned int is_odd(struct tree_node *node) {
    if (node == NULL) return 0;
    return (1 + is_odd(node->left) + is_odd(node->right)) % 2;
}}_

_code{unsigned int gcd(unsigned int m, unsigned int n) {
    if (n == 0) return m;
    return gcd(n, m % n);
}}_

_code{long int total(struct list_node *node) {
    if (node == NULL) return 0;
    return node->number + total(node->next);
}}_

_code{char find_minimum(struct list_node *node) {
    if (node->next == NULL) return node->number;
    char min_in_rest = find_minimum(node->next);
    return (node->number < min_in_rest) ? node->number : min_in_rest;
}}_

_code{void make_double(struct list_node *node) {
    if (node == NULL) return;
    node->number *= 2;
    make_double(node->next);
}}_

_code{unsigned int divide(unsigned int dividend, unsigned int divisor) {
    if (dividend < divisor) return 0;
    return 1 + divide(dividend - divisor, divisor);
}}_

_code{unsigned int count_leaves(struct tree_node *node) {
    if (node == NULL) return 0;
    if (node->left == NULL && node->right == NULL) return 1;
    return count_leaves(node->left) + count_leaves(node->right);
}}_
